using Vec=FieldVector<Double>;
YeeComponent& current(EBFieldGrid& f,unsigned a){return a==0?f.jx():(a==1?f.jy():f.jz());}
double cardinal(double x,unsigned m){const double t=.5*(m+1)-std::abs(x);if(t<=0.)return 0.;double sum=0.,choose=1.,fac=1.;for(unsigned j=2;j<=m;++j)fac*=j;for(unsigned j=0;j<=m+1&&j<t;++j){sum+=(j%2?-1.:1.)*choose*std::pow(t-j,(int)m);choose*=double(m+1-j)/(j+1);}return sum/fac;}
double independent(double x,unsigned m){const double p=5,a=p/6,b=3*p/40+p*(p-1)/72,d=5*p/112+p*(p-1)/80+p*(p-1)*(p-2)/1296;double out=0.;for(int k=-3;k<=3;++k){const unsigned j=std::abs(k);double c=j==0?1+a/2+3*b/8+5*d/16:(j==1?-a/4-b/4-15*d/64:(j==2?b/16+3*d/32:-d/64));out+=c*cardinal(x-k,m);}return out;}
void charge(YeeComponent& rho,const EBGridGeometry& g,const Vec& origin,const Vec& p,double q){const double x=(p[0]-origin[0])/g.dx,y=(p[1]-origin[1])/g.dy,z=(p[2]-origin[2])/g.dz;const auto i=(std::size_t)std::floor(x),j=(std::size_t)std::floor(y);const auto b=longitudinal_shape::basis(z);for(unsigned k=0;k<b.count;++k)for(unsigned a=0;a<2;++a)for(unsigned c=0;c<2;++c)rho(i+a,j+c,b.first+k)+=q/(g.dx*g.dy*g.dz)*(a?x-i:1-x+i)*(c?y-j:1-y+j)*b.v[k];}
int main(int argc,char** argv){MPI_Init(&argc,&argv);int rank=0,size=1;MPI_Comm_rank(MPI_COMM_WORLD,&rank);MPI_Comm_size(MPI_COMM_WORLD,&size);try{
 if(argc!=2)throw std::runtime_error("Need independent output directory");createDirectories(argv[1],MPI_COMM_WORLD);
 double basisError=0.;for(unsigned n=0;n<400;++n)for(bool edge:{false,true}){const double x=-2.71+.071*n;const auto b=longitudinal_shape::basis(x,edge);double sum=0.;for(unsigned k=0;k<b.count;++k){sum+=b.v[k];basisError=std::max(basisError,std::abs(b.v[k]-independent(x-b.first-k-(edge?.5:0.),edge?4:5)));}if(std::abs(sum-1)>5e-14)throw std::runtime_error("Quintic partition of unity");}if(basisError>5e-14)throw std::runtime_error("Quintic basis differs from independent 1D model");
 const double dz=1.2543262415359034e-6;EBGridGeometry g(8,9,16,5e-6,5e-6,dz,dz/SI::c,EBMaxwellSolver::CowanZ),gg=g;gg.nz*=size;EBFieldGrid f(g),gold(gg);Vec origin(0.);origin[2]=.018312345;Vec local(origin);local[2]+=rank*g.nz*dz;longitudinal_shape::Current d(f,MPI_COMM_WORLD),dg(gold,MPI_COMM_SELF);d.clear();dg.clear();YeeComponent before(gg.nx+1,gg.ny+1,gg.nz+1),after(gg.nx+1,gg.ny+1,gg.nz+1);
 unsigned particles=0;for(unsigned n=0;n<111;++n){Vec x(origin),y(origin);x[0]+=(2.1+.021*(n%100))*g.dx;x[1]+=(2.8+.031*(n%80))*g.dy;x[2]+=(7.15+(gg.nz-14.3)*((n*37)%111)/111.)*dz;y=x;y[0]+=(n%2?.37:-.23)*g.dx;y[1]+=(n%3?.29:-.41)*g.dy;y[2]+=(n%2?.43:-.34)*dz;const double q=-SI::elementaryCharge;dg.deposit(origin,x,y,q);charge(before,gg,origin,x,q);charge(after,gg,origin,y,q);++particles;
  const double a=(x[2]-local[2])/dz,b=(y[2]-local[2])/dz;double lo=0.,hi=1.;if(b>a){lo=std::max(lo,-a/(b-a));hi=std::min(hi,(g.nz-a)/(b-a));}else{lo=std::max(lo,(g.nz-a)/(b-a));hi=std::min(hi,-a/(b-a));}if(hi>lo){Vec l(x),h(x);for(unsigned k=0;k<3;++k){l[k]=x[k]+lo*(y[k]-x[k]);h[k]=x[k]+hi*(y[k]-x[k]);}d.deposit(local,l,h,q);}
 }
 d.complete();EBZSlabHaloExchange exchange(MPI_COMM_WORLD);exchange.sumSharedTangentialCurrent(f);double error=0.,scale=0.;for(unsigned a=0;a<3;++a){auto& v=current(f,a);auto& ref=current(gold,a);for(std::size_t k=0;k<v.nz();++k)for(std::size_t j=0;j<v.ny();++j)for(std::size_t i=0;i<v.nx();++i){scale=std::max(scale,std::abs(ref(i,j,k+rank*g.nz)));error=std::max(error,std::abs(v(i,j,k)-ref(i,j,k+rank*g.nz)));}}double rel=error/std::max(scale,1e-300),global=0.;MPI_Allreduce(&rel,&global,1,MPI_DOUBLE,MPI_MAX,MPI_COMM_WORLD);if(global>1e-9)throw std::runtime_error("Wide current MPI/serial mismatch");
 long double continuity=0.;for(std::size_t k=0;k<=gg.nz;++k)for(std::size_t j=0;j<=gg.ny;++j)for(std::size_t i=0;i<=gg.nx;++i){long double div=(i<gg.nx?gold.jx()(i,j,k):0.)-(i?gold.jx()(i-1,j,k):0.);div/=gg.dx;div+=((j<gg.ny?gold.jy()(i,j,k):0.)-(j?gold.jy()(i,j-1,k):0.))/gg.dy;div+=((k<gg.nz?gold.jz()(i,j,k):0.)-(k?gold.jz()(i,j,k-1):0.))/gg.dz;continuity+=std::abs((long double)after(i,j,k)-before(i,j,k)+gg.dt*div)*gg.dx*gg.dy*gg.dz/(particles*SI::elementaryCharge);}if(continuity>1e-10)throw std::runtime_error("Quintic 3D continuity failed");
 for(unsigned a=0;a<3;++a){auto& e=a==0?f.ex():(a==1?f.ey():f.ez());for(std::size_t k=0;k<e.nz();++k)for(std::size_t j=0;j<e.ny();++j)for(std::size_t i=0;i<e.nx();++i)e(i,j,k)=std::sin(.17*i+.23*j+.31*(k+rank*g.nz)+a);}
 source_coupling_math::NativeHalo halo;halo.exchange(f,MPI_COMM_WORLD,false,8);double haloError=0.;for(unsigned a=0;a<3;++a){const auto& e=a==0?f.ex():(a==1?f.ey():f.ez());for(long long k=-8;k<(long long)e.nz()+8;++k)if((k>=0&&k<(long long)e.nz())||halo.contains(k,e.nz()))haloError=std::max(haloError,std::abs(halo.value(e,a,2,3,k)-std::sin(.17*2+.23*3+.31*(k+rank*(long long)g.nz)+a)));}if(haloError>1e-13)throw std::runtime_error("Wide electric halo indexing failed");
 if(rank==0){EBGridGeometry refg(16,16,48,5e-6,5e-6,dz,dz/SI::c,EBMaxwellSolver::CowanZ);std::vector<RelativisticParticleSI> p(3);for(unsigned i=0;i<p.size();++i){p[i].position=Vec(0.);p[i].position[0]=(6.1+.3*i)*refg.dx;p[i].position[1]=(7.2+.2*i)*refg.dy;p[i].position[2]=(14.2+5.4*i)*refg.dz;p[i].charge=-SI::elementaryCharge;p[i].mass=SI::electronMass;}const std::size_t guards[3]={0,0,0};const std::string path=std::string(argv[1])+"/reference";verification::BlockedCowanReference ref(refg,Vec(0.),p,.23,guards,8,path,MPI_COMM_SELF,true);YeeComponent rho(17,17,49);for(const auto& q:p)charge(rho,refg,Vec(0.),q.position,q.charge);double re=0.,rs=0.;for(unsigned k=1;k<48;++k)for(unsigned j=1;j<16;++j)for(unsigned i=1;i<16;++i){rs=std::max(rs,std::abs(rho(i,j,k)));re=std::max(re,std::abs(rho(i,j,k)-ref.chargeDensity(i,j,k)));}if(re/std::max(rs,1e-300)>1e-13)throw std::runtime_error("Blocked quintic source mismatch");auto reader=verification::BlockedCowanReference::openPrepared(refg,Vec(0.),.23,guards,8,path,MPI_COMM_SELF,true);bool rejected=false;try{auto wrong=verification::BlockedCowanReference::openPrepared(refg,Vec(0.),.23,guards,8,path,MPI_COMM_SELF,false);}catch(...){rejected=true;}if(!rejected)throw std::runtime_error("Reference shape metadata negative control");}
 if(rank==0)std::cout<<std::setprecision(18)<<"{\"passed\":true,\"ranks\":"<<size<<",\"independent_basis_error\":"<<basisError<<",\"MPI_current_relative_error\":"<<global<<",\"continuity_L1_over_abs_charge\":"<<continuity<<",\"wide_E_halo_error\":"<<haloError<<"}\n";
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';MPI_Abort(MPI_COMM_WORLD,1);}MPI_Finalize();return 0;}
